mapper.select:
SELECT p.id, p.name FROM product_info p LEFT JOIN project_info pi
ON p.id = pi.product_id AND pi.is_deleted = FALSE
left JOin (select pt.product_id, COALESCE(min(pp.seq),max(ppe.seq)) as seq from project_task pt
left join project_phase pp on pt.phase_id = pp.id and pt.product_id = pp.product_id and pt.status in
(0,1,2,3,7,9,10) AND pp.is_deleted = FALSE
left join project_phase ppe on pt.phase_id = ppe.id and pt.product_id = ppe.product_id and pt.status = 4 AND
ppe.is_deleted = FALSE
WHERE pt.is_deleted = FALSE
GROUP BY pt.product_id) pp on p.id = pp.product_id
left join project_phase pph on pp.product_id = pph.product_id and pp.seq = pph.seq AND pph.is_deleted = FALSE
WHERE p.is_finished_product_dev = 1 AND p.is_deleted = FALSE

    AND p.category_id IN

        #{categoryId}



    AND (p.name ILIKE concat('%',#{params.searchKeyword}::text,'%')
    OR p.id IN (SELECT pd.product_id FROM product_detail pd WHERE pd.sku_no LIKE
    concat('%',#{params.searchKeyword}::text,'%'))
    OR p.spu_no ILIKE concat('%',#{params.searchKeyword}::text,'%'))


    AND P.approval_status IN

        #{state}




    AND P.id IN

        #{productId}




    AND P.id NOT IN

        #{productId}




    AND p.grade_id IN

        #{gradeId}




    AND p.brand_id IN

        #{brandId}




    AND p.progress_status IN

        #{progressStatus}




    AND pi.charge_id IN

        #{chargeId}





    AND p.property_id IN

        #{propertyId}




    AND pph.name IN

        #{phaseName}




    AND

        string_to_array(#{chargeId},',') && string_to_array(p.charge_id,',')




    AND p.create_time >= #{params.createTimeList[0]} and (#{params.createTimeList[1]}::TIMESTAMP + INTERVAL '1
    DAY' ) > p.create_time


    and p.project_charge_id in

        #{item}



    and p.charge_id in

        #{item}



    and exists (
    select id from project_members where product_id = p.id and  is_deleted = false
    and  member_id in

        #{item}

    )


    and p.create_user_id in

        #{item}



    AND (p.id IN (SELECT pt.product_id FROM project_task pt WHERE 1 = 1 ${params.permissionSql})
    )

ORDER BY p.create_time DESC

SELECT pi.id AS productId,pi.name AS productName,pj.id AS projectId FROM product_info pi Left JOIN project_info pj ON pi.id=pj.product_id AND pj.is_deleted = FALSE WHERE pi.is_finished_product_dev = 1 AND pi.is_deleted = FALSE AND (pj.project_status IS NULL OR pj.project_status!=#{projectStatus})
AND pi.id NOT IN
#{archiveProductId}

SELECT p.id AS product_id, p.name, p.grade, p.charge_name AS productChargeName, pi.project_status, p.brand_name, pi.id AS projectId, p.grade_id, p.charge_id AS productChargeId, p.project_charge_id AS projectChargeId, p.type, p.approval_status, pi.charge_name AS projectChargeName, p.create_time, p.progress_status, p.image_url, p.property, p.category, pi.end_time, pi.start_time, p.create_user_name, p.spu_no, pph.name as projectPhase, p.application_category_id FROM product_info p LEFT JOIN project_info pi ON p.id = pi.product_id AND pi.is_deleted = FALSE LEFT JOIN (select pt.product_id, COALESCE(min(pp.seq),max(ppe.seq)) as seq from project_task pt LEFT JOIN project_phase pp on pt.phase_id = pp.id and pt.product_id = pp.product_id and pt.status in (0,1,2,3,7,9,10) AND pp.is_deleted = FALSE LEFT JOIN project_phase ppe on pt.phase_id = ppe.id and pt.product_id = ppe.product_id and pt.status = 4 AND ppe.is_deleted = FALSE WHERE pt.is_deleted = FALSE GROUP BY pt.product_id) pp on p.id = pp.product_id LEFT JOIN project_phase pph on pp.product_id = pph.product_id and pp.seq = pph.seq AND pph.is_deleted = FALSE WHERE p.is_finished_product_dev = 1 AND p.is_deleted = FALSE AND P.id NOT IN (SELECT product_id FROM product_archive WHERE is_deleted=FALSE)
AND p.id IN
#{id}
and ${params.sqlMap.default}
ORDER BY p.create_time DESC

SELECT p.name AS productName, pt.name AS taskName, pt.plan_start_time, pt.plan_end_time, pt.charge_id, pt.charge_name, pt.reality_start_time, pt.reality_end_time, pt.status, date_part('day',pt.plan_end_time - pt.plan_start_time) + 1 AS expectedDay, date_part('day',pt.reality_end_time - pt.reality_start_time) + 1 AS realityDay, pt.work_period FROM product_info p INNER JOIN project_task pt ON p.id = pt.product_id AND pt.is_deleted = FALSE LEFT JOIN project_info pi ON p.id = pi.product_id AND pi.is_deleted = FALSE LEFT JOIN (select pt.product_id, COALESCE(min(pp.seq),max(ppe.seq)) as seq from project_task pt LEFT JOIN project_phase pp on pt.phase_id = pp.id and pt.product_id = pp.product_id and pt.status in (0,1,2,3,7,9,10) AND pp.is_deleted = FALSE LEFT JOIN project_phase ppe on pt.phase_id = ppe.id and pt.product_id = ppe.product_id and pt.status = 4 AND ppe.is_deleted = FALSE WHERE pt.is_deleted = FALSE GROUP BY pt.product_id) pp on p.id = pp.product_id INNER JOIN project_phase pph on pt.product_id = pph.product_id and pp.seq = pph.seq AND pph.is_deleted = FALSE WHERE p.is_finished_product_dev = 1 AND p.is_deleted = FALSE AND P.id NOT IN (SELECT product_id FROM product_archive WHERE is_deleted=FALSE)
AND p.id IN
#{id}
and ${params.sqlMap.default}
ORDER BY p.create_time DESC

SELECT p.id AS product_id, p.name, p.grade, p.charge_name AS productChargeName, pi.project_status, p.brand_name, pi.id AS projectId, p.grade_id, p.charge_id AS productChargeId, p.project_charge_id AS projectChargeId, p.type, p.approval_status, pi.charge_name AS projectChargeName, p.create_time, p.progress_status, p.image_url, p.property, p.category, pi.end_time, pi.start_time, p.create_user_name, p.spu_no, pph.name as projectPhase, p.application_category_id FROM product_info p LEFT JOIN project_info pi ON p.id = pi.product_id AND pi.is_deleted = FALSE LEFT JOIN (select pt.product_id, COALESCE(min(pp.seq),max(ppe.seq)) as seq from project_task pt LEFT JOIN project_phase pp on pt.phase_id = pp.id and pt.product_id = pp.product_id and pt.status in (0,1,2,3,7,9,10) AND pp.is_deleted = FALSE LEFT JOIN project_phase ppe on pt.phase_id = ppe.id and pt.product_id = ppe.product_id and pt.status = 4 AND ppe.is_deleted = FALSE WHERE pt.is_deleted = FALSE GROUP BY pt.product_id) pp on p.id = pp.product_id LEFT JOIN project_phase pph on pp.product_id = pph.product_id and pp.seq = pph.seq AND pph.is_deleted = FALSE WHERE p.is_finished_product_dev = 1 AND p.is_deleted = FALSE AND (string_to_array( p.charge_id,',') && string_to_array(#{userId}, ',') or p.project_charge_id=#{userId} or p.id in (select product_id from project_task where is_deleted=false and string_to_array( charge_id,',') && string_to_array(#{userId}, ','))) AND P.id NOT IN (SELECT product_id FROM product_archive WHERE is_deleted=FALSE)
AND p.id IN
#{id}
and ${params.sqlMap.default}
ORDER BY p.create_time DESC

