AND p.id IN
#{id}
and ${params.sqlMap.default}
ORDER BY pt.create_time DESC

SELECT p.id AS product_id, p.name, p.grade, p.charge_name AS productChargeName, pi.project_status, p.brand_name, pi.id AS projectId, p.grade_id, p.charge_id AS productChargeId, p.project_charge_id AS projectChargeId, p.type, p.approval_status, pi.charge_name AS projectChargeName, p.create_time, p.progress_status, p.image_url, p.property, p.category, pi.end_time, pi.start_time, p.create_user_name, p.spu_no, pph.name as projectPhase, p.application_category_id FROM product_info p LEFT JOIN project_info pi ON p.id = pi.product_id AND pi.is_deleted = FALSE LEFT JOIN (select pt.product_id, COALESCE(min(pp.seq),max(ppe.seq)) as seq from project_task pt LEFT JOIN project_phase pp on pt.phase_id = pp.id and pt.product_id = pp.product_id and pt.status in (0,1,2,3,7,9,10) AND pp.is_deleted = FALSE LEFT JOIN project_phase ppe on pt.phase_id = ppe.id and pt.product_id = ppe.product_id and pt.status = 4 AND ppe.is_deleted = FALSE WHERE pt.is_deleted = FALSE GROUP BY pt.product_id) pp on p.id = pp.product_id LEFT JOIN project_phase pph on pp.product_id = pph.product_id and pp.seq = pph.seq AND pph.is_deleted = FALSE WHERE p.is_finished_product_dev = 1 AND p.is_deleted = FALSE AND P.id NOT IN (SELECT product_id FROM product_archive WHERE is_deleted=FALSE) AND p.id IN (SELECT product_id FROM user_add_product WHERE is_deleted=FALSE AND user_id=#{userId})
AND p.id IN
